"/**
 * Cinejoy webOS - Spatial Remote Focus & Navigation System
 * Strict 10-Foot TV Focus Standard (#95FF50 14.8:1 High-Contrast Brand Lime & Pure White Halo)
 * Target: webOS 8.5.0 Remote Controls & D-Pad (1920x1080)
 */

/* ==========================================================================
   Base Navigable Element Attributes & GPU Layer Promotion
   ========================================================================== */
[data-nav="true"] {
  outline: none;
  -webkit-tap-highlight-color: transparent;
  will-change: transform, box-shadow;
  transform: translateZ(0);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

/* ==========================================================================
   Active Focused Element Standard (Dual-Layer 5px White + Lime Glow Halo)
   ========================================================================== */
[data-nav="true"].focused,
[data-nav="true"]:focus-visible,
[data-nav="true"]:focus,
.focused,
.tv-focused {
  outline: none !important;
  border-color: #FFFFFF !important;
  box-shadow: 0 0 0 5px #FFFFFF, 0 0 28px rgba(149, 255, 80, 0.65) !important; /* Brand lime #95FF50 atmospheric glow */
  transform: scale(1.08) translateZ(0) !important;
  z-index: 50 !important;
  transition: transform 0.2s var(--cinema-ease-decel, cubic-bezier(0.2, 0.8, 0.2, 1)),
              box-shadow 0.2s var(--cinema-ease-decel, cubic-bezier(0.2, 0.8, 0.2, 1)),
              border-color 0.2s ease,
              background-color 0.18s ease,
              color 0.18s ease !important;
}

/* ==========================================================================
   Component-Specific Focus Refinements
   ========================================================================== */

/* Brand Container in Header */
.brand-container[data-nav="true"].focused,
.brand-container.focused {
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  background-color: rgba(255, 255, 255, 0.12) !important;

