      if (global.SpatialNav && typeof global.SpatialNav.on === 'function') {
        global.SpatialNav.on('deadend', function (data) {
          if (!data) return;
          var curView = (global.CinejoyApp && global.CinejoyApp.state && global.CinejoyApp.state.currentView) || 'search';
          if (curView === 'search' && data.direction === 'down') {
            if (data.element && data.element.closest('.tv-keyboard-container')) {
              self.jumpToResults();
            }
          }
        });

        // Re-engage keyboard trap when navigating back into the virtual keyboard
        global.SpatialNav.on('focus', function (data) {
          if (!data || !data.element || !self.keyboard) return;
          var curView = (global.CinejoyApp && global.CinejoyApp.state && global.CinejoyApp.state.currentView) || 'search';
          if (curView === 'search') {
            if (self.keyboard.contains(data.element)) {
              if (!self.isTrapped) {
                self.engageTrap();
              }
            } else {
              var grid = self.resultsGrid || document.getElementById('search-results-grid');
              if (grid && grid.contains(data.element)) {
                if (self.isTrapped) {
                  self.releaseTrap();
                }
              }
            }
          }
        });
      }

      this.keyboard.addEventListener('focusin', function () {
        var curView = (global.CinejoyApp && global.CinejoyApp.state && global.CinejoyApp.state.currentView) || 'search';
